(()=>{const works=[{"id": "warm-textures", "type": "image", "title": "Warm textures", "src": "assets/works/warm-vanity.png", "alt": "A completed vanity with an arched mirror, textured wall and illuminated niches", "description": "An arched mirror, warm lighting and illuminated niches bring depth to this vanity space.", "details": ["Arched mirror", "Illuminated niches", "Textured wall"]}, {"id": "light-form", "type": "image", "title": "Light & form", "src": "assets/works/bathroom-overview.jpg", "alt": "Completed bathroom with a glass shower enclosure, arched mirror, pedestal basin and circular window", "description": "A look inside the completed bathroom: a sculpted ceiling, glass shower enclosure and softly lit vanity.", "details": ["Glass shower enclosure", "Pedestal basin", "Ambient lighting"]}, {"id": "closer-look", "type": "image", "title": "Sculpted texture", "src": "assets/works/sculpted-basin.jpg", "alt": "A dark ribbed pedestal basin with a slim black shelf, photographed during installation", "description": "A sculptural ribbed pedestal basin and slim black shelf, captured as the space takes shape.", "details": ["Ribbed pedestal basin", "Slim black shelf", "Installation in progress"]}, {"id": "classic-details", "type": "video", "title": "Classic detailing", "src": "assets/works/walkthrough-01.mp4", "poster": "assets/works/classic-details-poster.png", "alt": "Video of an ornate double vanity with a decorative mirror and gold-toned fittings", "description": "A video walkthrough of a vanity with decorative cabinetry, a statement mirror and twin vessel basins.", "details": ["Decorative cabinetry", "Twin basins", "Video walkthrough"]}, {"id": "modern-warmth", "type": "video", "title": "Modern warmth", "src": "assets/works/walkthrough-02.mp4", "poster": "assets/works/modern-warmth-poster.png", "alt": "Video of a softly lit bathroom vanity with a rectangular LED mirror and textured tiles", "description": "Explore the lighting, textured surfaces and contemporary fittings in this completed space.", "details": ["LED mirror", "Textured surfaces", "Video walkthrough"]}];let current=0;const dialog=document.getElementById('projectmodal'),media=document.getElementById('work-modal-media');function stopVideo(){media.querySelectorAll('video').forEach(v=>v.pause())}function show(index){stopVideo();current=(index+works.length)%works.length;const item=works[current];let node;if(item.type==='video'){node=document.createElement('video');node.controls=true;node.playsInline=true;node.preload='metadata';node.poster=item.poster;node.setAttribute('aria-label',item.alt);const source=document.createElement('source');source.src=item.src;source.type='video/mp4';node.append(source)}else{node=document.createElement('img');node.src=item.src;node.alt=item.alt;node.decoding='async'}media.replaceChildren(node);document.getElementById('project-modal-title').textContent=item.title;document.getElementById('project-modal-description').textContent=item.description;document.getElementById('work-gallery-count').textContent=String(current+1).padStart(2,'0')+' / '+String(works.length).padStart(2,'0')+' · '+(item.type==='video'?'VIDEO':'PHOTOGRAPH');document.getElementById('project-modal-materials').replaceChildren(...item.details.map(text=>{const span=document.createElement('span');span.textContent=text;return span}));dialog.scrollTop=0}document.querySelectorAll('[data-work]').forEach(button=>button.addEventListener('click',()=>{show(works.findIndex(w=>w.id===button.dataset.work));dialog.showModal();dialog.scrollTop=0}));document.getElementById('work-previous').addEventListener('click',()=>show(current-1));document.getElementById('work-next').addEventListener('click',()=>show(current+1));dialog.addEventListener('close',stopVideo);dialog.addEventListener('keydown',event=>{if(event.target.closest('video,button,a,input'))return;if(event.key==='ArrowRight'){event.preventDefault();show(current+1)}if(event.key==='ArrowLeft'){event.preventDefault();show(current-1)}});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.05});document.querySelectorAll('.work-card,.hecuba-image,.hecuba-copy,.cabin-intro,.crew-process article,.cabin-photo').forEach(el=>{el.classList.add('portfolio-reveal');observer.observe(el)})}})();